        { k = "boss", title = "格里哈斯特（鱼人）", boss = "格里哈斯特", eid = 2914, alias = { "Geilhast", "Gelihast" }, ref = true, route = { "从西边的洞出来，绕阿斯卡之池南边往东，进东边的鱼人洞，格里哈斯特在洞里。", "实测从萨利维丝到这里约 15 分钟（含清怪）。" }, tips = { "鱼人成群，别一次拉太多。", "经典里他旁边有「格里哈斯特神殿」，打完可以点，给一个增益。" }, loot = "鱼人皮包（背包 15%）· 海藻手套（锁甲手 50%）· 暗礁战斧（双手斧 50%）" },
        { k = "boss", title = "洛古斯·杰特（稀有，可选）", boss = "洛古斯·杰特", eid = 2913, alias = { "Lorgus Jett" }, opt = true, ref = true, route = { "从鱼人洞往东南的通道走，一路长坡下到下层的月神废墟（有废墟的大湖区）。", "洛古斯·杰特是稀有，不一定刷，刷在废墟一带。" }, tips = { "没刷就点「下一步」跳过。" }, quests = { { s = "H", t = "「上古之神的仆从」后续要杀他：先在副本入口附近打黑暗深渊潮汐祭司，掉「潮湿的便笺」接任务" } }, loot = "腐根长弓 · 暮光木槌 · 背信弃义的足具" },
