    src = "首领 / encounterID / 顺序：《无限》客户端 DB2；掉落 / 任务 / 入口：GearInsight 数据；地图：客户端里的经典副本图，首领点 = 冒险手册坐标（零售 / 经典 DB2）；小地图：客户端小地图贴图，首领点 = 经典刷怪点世界坐标换算",
    more = "燃烧地狱卫士 · 霍克·巴什古德 · 尖石屠夫 · 尖石统帅 · 尖石首席法师 · 班诺克·巨斧 · 水晶之牙 · 莫尔·灰蹄",
    steps = {
        { k = "boss", title = "欧莫克大王", boss = "欧莫克大王", eid = 267, alias = { "Highlord Omokk" }, route = { "入口：灼热峡谷", "地图 1 号点（霍德玛尔城）" }, quests = { { t = "「基布雷尔的特殊宠物」：到黑石塔去找到血斧座狼幼崽。使用笼子来捕捉这些凶猛的小野兽，然后把笼中的座狼幼崽交给基布雷尔。" }, { t = "「晋升印章」：到尘泥沼泽中的巨龙沼泽去。找到上古老龙埃博斯塔夫，对他发起无情的攻击，直到他的意志被摧毁。" }, { t = "「最后的石板」：将第五块和第六块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。" }, { t = "「蜘蛛卵」：到黑石塔去为基布雷尔收集15枚尖塔蜘蛛卵。$B$B听说那些蜘蛛周围有许多这样的卵。" }, { t = "「乌洛克」：阅读瓦罗什的卷轴。将瓦罗什的蟑螂交给他。" }, { s = "H", t = "「狡猾的比修」：到黑石塔去查明比修的下落。" }, { s = "H", t = "「比修的装置」：找到比修的装置并把它们还给她。你记得她说过她把装置藏在城市的最底层。" }, { s = "H", t = "「比修的侦察报告」：把比修的侦查报告交给卡加斯的雷克斯洛特。" }, { t = "…其余 4 个见插件「副本任务」页" }, { t = "「晋升印章」：找到三块命令宝石：燃棘宝钻、尖石宝钻和血斧宝钻。把它们和原始晋升印章一起交给维埃兰。" }, { s = "H", t = "「高图斯的命令」：杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。" }, { s = "A", t = "「麦克斯韦尔的任务」：到黑石塔去消灭指挥官沃恩、欧莫克大王和维姆萨拉克。完成任务之后回到麦克斯韦尔元帅处复命。" } }, loot = "元素长靴（锁甲脚，16.7%） · 尖石宝钻（任务物品任务，25%） · 欧莫克的头颅（任务物品任务，100%）" },
