        { k = "boss", title = "烟网蛛后", boss = "烟网蛛后", eid = 270, alias = { "Mother Smolderweb" }, route = { "地图 4 号点：换到「蛛网隧道」这一层" }, quests = { { t = "「蛛后的乳汁」：你可以在黑石塔的中心地带找到烟网蛛后。与她战斗，让她在你体内注入毒汁。如果你有能力的话，就杀死她吧。" } }, loot = "野性之心长靴（皮甲脚，25%）" },
        { k = "boss", title = "乌洛克", boss = "乌洛克", eid = 271, alias = { "Urok Doomhowl" }, route = { "地图 5 号点：换到「黑手大厅」这一层" }, loot = "《高级铸甲技术：第三卷》的上半部（任务物品任务，16%）" },
        { k = "boss", title = "军需官兹格雷斯", boss = "军需官兹格雷斯", eid = 272, alias = { "Quartermaster Zigris" }, route = { "地图 6 号点：换到「哈雷肯之巢」这一层" }, loot = "设计图：歼灭者（锻造配方，10%） · 军需官兹格雷斯的提箱（杂项，12.4%）" },
        { k = "boss", title = "哈雷肯", boss = "哈雷肯", eid = 274, alias = { "Halycon" }, route = { "地图 7 号点：在上一个首领的西边（哈雷肯之巢）" }, quests = { { s = "A", t = "「座狼之源」：到黑石塔去摧毁那里的座狼源头。当你离开的时候，赫林迪斯喊出了一个名字：哈雷肯。这个词就是兽人语中“座狼”的意思。" }, { s = "H", t = "「座狼的首领」：杀死血斧座狼的领袖，哈雷肯。" } } },
        { k = "boss", title = "奴役者基兹鲁尔", boss = "奴役者基兹鲁尔", eid = 273, alias = { "Gizrul the Slavener" }, route = { "地图 8 号点，就在上一个首领旁边" }, loot = "野性之心肩甲（皮甲肩部，25%）" },
